sys_script_fix.script:
var validArr = [{
    "TradeID": "R-205-3345",
    "reasonCode": "CONF",
    "reasonDesc": "FX Calculated by Approval"
}, {
    "TradeID": "D-238-2233",
    "reasonCode": "MATCH",
    "reasonDesc": "Cancellation from GHSS"
}];

var caseArr = [{
    "TradeRef": "D-238-2233",
    "caseID": "CS00092"
}, {
    "TradeRef": "R-205-3345",
    "caseID": "CS00091",
}];

var finalObject = {};
var finalArr = [];

//mapping
/*
{
  "R-205-3345": { "reasonCode": "CONF", "reasonDesc": "FX Calculated by Approval" },
  "D-238-2233": { "reasonCode": "MATCH", "reasonDesc": "Cancellation from GHSS" }
}
*/
var validMap = {};
validArr.forEach(function(item) {
    validMap[item.TradeID] = {
        reasonCode: item.reasonCode,
        reasonDesc: item.reasonDesc
    };
});

caseArr.forEach(function(caseItem) {
    var tradeRef = caseItem.TradeRef;
    if (validMap.hasOwnProperty(tradeRef)) { //comparison of newly created map and the case array newly created

        finalObject[tradeRef] = { // Use TradeRef (which matches TradeID) as the key
            "TradeRef": tradeRef, // Include TradeRef in the value object
			"caseID": caseItem.caseID, // Include TradeRef in the value object
            "reasonCode": validMap[tradeRef].reasonCode, //from validarray
            "reasonDesc": validMap[tradeRef].reasonDesc
        };
        finalArr.push(JSON.stringify(finalObject[tradeRef]) + ' ');
    }
});

gs.info(finalArr.toString());
